args.content:
:root {
  --ink: #1a1f24;
  --muted: #5c6670;
  --rule: #e2e6ea;
  --accent: #2f5d62;
  --bg: #fcfcfa;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  background: var(--bg);
  color: var(--ink);
  font: 17px/1.65 Georgia, "Iowan Old Style", "Times New Roman", serif;
}

main {
  max-width: 40rem;
  margin: 0 auto;
  padding: 4rem 1.4rem 5rem;
}

h1 {
  font-size: 2.1rem;
  letter-spacing: -0.01em;
  margin: 0 0 0.3rem;
}

.sub {
  color: var(--muted);
  font-size: 1.05rem;
  margin: 0 0 2.5rem;
  padding-bottom: 2rem;
  border-bottom: 1px solid var(--rule);
}

h2 {
  font-size: 1.15rem;
  text-transform: uppercase;
  letter-spacing: 0.07em;
  color: var(--accent);
  margin: 2.6rem 0 0.8rem;
}

p { margin: 0 0 1.1rem; }

ul { padding-left: 1.1rem; margin: 0 0 1.1rem; }
li { margin-bottom: 0.7rem; }

.box {
  background: #f3f1ec;
  border-left: 3px solid var(--accent);
  padding: 0.4rem 1.4rem 1rem;
  margin: 2.6rem 0;
}

.box h2 { margin-top: 1.2rem; }

a { color: var(--accent); }

footer {
  margin-top: 3.5rem;
  padding-top: 1.6rem;
  border-top: 1px solid var(--rule);
}

.fine {
  color: var(--muted);
  font-size: 0.85rem;
  line-height: 1.5;
}

@media (max-width: 30rem) {
  main { padding-top: 2.5rem; }
  h1 { font-size: 1.7rem; }
}
